import java.util.*;
import java.lang.*;

class Solution {
    public List<String> separateParenGroups(String paren_string) {
        List<String> result = new ArrayList<>();
        List<Character> currentString = new ArrayList<>();
        int currentDepth = 0;

        for (char c : paren_string.toCharArray()) {
            if (c == '(') {
                currentDepth++;
                currentString.add(c);
            } else if (c == ')') {
                currentDepth--;
                currentString.add(c);

                if (currentDepth == 0) {
                    result.add(new String(currentString.stream().map(String::valueOf).toArray(String[]::new)));
                    currentString.clear();
                }
            }
        }

        return result;
    }
}
