import java.util.*;
import java.lang.*;

class Solution {
    public List<Double> findClosestElements(List<Double> numbers) {
        if (numbers == null || numbers.size() < 2) {
            return new ArrayList<>();
        }

        double closestPair[] = new double[2];
        double distance = Double.MAX_VALUE;

        for (int idx = 0; idx < numbers.size(); idx++) {
            for (int idx2 = idx + 1; idx2 < numbers.size(); idx2++) {
                double newDistance = Math.abs(numbers.get(idx) - numbers.get(idx2));
                if (newDistance < distance) {
                    distance = newDistance;
                    closestPair[0] = Math.min(numbers.get(idx), numbers.get(idx2));
                    closestPair[1] = Math.max(numbers.get(idx), numbers.get(idx2));
                }
            }
        }

        List<Double> result = new ArrayList<>();
        result.add(closestPair[0]);
        result.add(closestPair[1]);
        return result;
    }
}
