class Solution {
    public int fizzBuzz(int n) {
        List<Integer> ns = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (i % 11 == 0 || i % 13 == 0) {
                ns.add(i);
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int num : ns) {
            sb.append(num);
        }
        String s = sb.toString();
        int ans = 0;
        for (char c : s.toCharArray()) {
            if (c == '7') {
                ans++;
            }
        }
        return ans;
    }
}
