class Solution {
    public int largestPrimeFactor(int n) {
        boolean isPrime(int k) {
            if (k < 2) {
                return false;
            }
            for (int i = 2; i < k - 1; i++) {
                if (k % i == 0) {
                    return false;
                }
            }
            return true;
        }
        int largest = 1;
        for (int j = 2; j <= n; j++) {
            if (n % j == 0 && isPrime(j)) {
                largest = Math.max(largest, j);
            }
        }
        return largest;
    }
}
