class Solution {
    public int countNums(List<Integer> arr) {
        int count = 0;
        for (Integer i : arr) {
            int sum = digitsSum(i);
            if (sum > 0) {
                count++;
            }
        }
        return count;
    }

    private int digitsSum(int n) {
        int neg = 1;
        if (n < 0) {
            n = -1 * n;
            neg = -1;
        }
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return sum * neg;
    }
}
