class Solution {
    public String matchParens(List<String> lst) {
        String S1 = lst.get(0) + lst.get(1);
        String S2 = lst.get(1) + lst.get(0);
        return check(S1) || check(S2) ? "Yes" : "No";
    }

    private boolean check(String s) {
        int val = 0;
        for (char i : s.toCharArray()) {
            if (i == '(') {
                val = val + 1;
            } else {
                val = val - 1;
            }
            if (val < 0) {
                return false;
            }
        }
        return val == 0;
    }
}
