                    if (j != 0) {
                        temp.add(grid.get(i).get(j - 1));
                    }

                    if (i != n - 1) {
                        temp.add(grid.get(i + 1).get(j));
                    }

                    if (j != n - 1) {
                        temp.add(grid.get(i).get(j + 1));
                    }

                    val = Math.min(val, Collections.min(temp));
                }
            }
        }

        List<Integer> ans = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            if (i % 2 == 0) {
                ans.add(1);
            } else {
                ans.add(val);
            }
        }
        return ans;
    }
}
