class Solution {
    public List<Integer> orderByPoints(List<Integer> nums) {
        nums.sort(Comparator.comparingInt(this::digitsSum));
        return nums;
    }

    private int digitsSum(int n) {
        int neg = 1;
        if (n < 0) {
            n = -1 * n;
            neg = -1;
        }
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return sum * neg;
    }
}
