class Solution {
    public int specialFilter(List<Integer> nums) {
        int count = 0;
        for (Integer num : nums) {
            if (num > 10) {
                int[] oddDigits = {1, 3, 5, 7, 9};
                String numberAsString = num.toString();
                int firstDigit = Character.getNumericValue(numberAsString.charAt(0));
